import '@design-schema/lit';
import { html } from 'lit';
import type { TabsTab } from '@design-schema/lit';

const TABS: TabsTab[] = [
  { id: 'overview', label: 'Overview' },
  { id: 'activity', label: 'Activity', badge: '3' },
  { id: 'files', label: 'Files', icon: 'external' },
  { id: 'members', label: 'Members', disabled: true },
];

html`
  <ds-tabs label="Project sections" .tabs=${TABS}>
    <ds-tab-panel id="overview">A summary of the project: status, owner and recent changes.</ds-tab-panel>
    <ds-tab-panel id="activity">A chronological feed of comments, edits and status changes.</ds-tab-panel>
    <ds-tab-panel id="files">Every file attached to this project, newest first.</ds-tab-panel>
    <ds-tab-panel id="members">The people with access to this project and their roles.</ds-tab-panel>
  </ds-tabs>
`;

